-- Applied migration version: 20261020031243.
begin;
create table public.operations_crawl_issues(
 id uuid primary key default gen_random_uuid(),brand_slug text not null references public.brands(slug),country_code text not null check(country_code in('KR','JP','FR','IT','ES','US','SG','HK')),sku text not null check(sku~'^[A-Z0-9][A-Z0-9._/-]{1,119}$'),stage text not null check(stage in('collection','validation','image','storage','publication','price')),kind text not null check(kind in('failure','price_unavailable')),reason_code text not null check(reason_code~'^[A-Z0-9_]{1,80}$'),official_url text not null check(official_url~'^https://'),status text not null default 'open' check(status in('open','manual_pending','published','auto_resolved','dismissed')),first_seen_at timestamptz not null,last_seen_at timestamptz not null,run_key text not null,occurrences integer not null default 1,revision integer not null default 1,resolution text,resolved_at timestamptz,unique(brand_slug,country_code,sku,stage));
create index crawl_issue_queue on public.operations_crawl_issues(status,last_seen_at desc,id);
create table public.operations_crawl_issue_events(event_key text primary key check(event_key~'^[a-f0-9]{64}$'),issue_id uuid references public.operations_crawl_issues(id),brand_slug text not null references public.brands(slug),country_code text not null check(country_code in('KR','JP','FR','IT','ES','US','SG','HK')),sku text not null,outcome text not null check(outcome in('failure','price_unavailable','verified')),observed_at timestamptz not null);
create index crawl_issue_event_target on public.operations_crawl_issue_events(issue_id);
create index crawl_issue_event_identity on public.operations_crawl_issue_events(brand_slug,country_code,sku,observed_at desc);
create table public.operations_crawl_sync_runs(run_key text primary key check(length(run_key)<=200),source text not null check(source in('local','github','backfill')),last_sync_at timestamptz not null default now(),finished boolean not null default false,received_count integer not null default 0);
do $$declare t text;begin foreach t in array array['operations_crawl_issues','operations_crawl_issue_events','operations_crawl_sync_runs'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
create function public.operations_record_crawl_events(p_events jsonb,p_run_key text,p_source text,p_finished boolean default false) returns jsonb language plpgsql security invoker set search_path='' as $$declare e jsonb;i public.operations_crawl_issues;inserted integer;n integer:=0;event_time timestamptz;begin
 if p_events is null or jsonb_typeof(p_events)<>'array' or jsonb_array_length(p_events)>100 or octet_length(p_events::text)>100000 or p_run_key is null or length(p_run_key) not between 1 and 200 or p_source is null or p_source not in('local','github','backfill') then raise exception 'invalid_events';end if;
 for e in select value from jsonb_array_elements(p_events) loop
  if e->>'event_key'!~'^[a-f0-9]{64}$' or e->>'sku'!~'^[A-Z0-9][A-Z0-9._/-]{1,119}$' or e->>'outcome' not in('failure','price_unavailable','verified') or e->>'reason_code'!~'^[A-Z0-9_]{1,80}$' or e->>'official_url'!~'^https://' or length(e->>'official_url')>500 or e->>'stage' not in('collection','validation','image','storage','publication','price') then raise exception 'invalid_event';end if;
  event_time:=(e->>'observed_at')::timestamptz;if event_time is null or event_time>now()+interval '1 minute' then raise exception 'invalid_observation';end if;
  insert into public.operations_crawl_issue_events(event_key,brand_slug,country_code,sku,outcome,observed_at) values(e->>'event_key',e->>'brand_slug',e->>'country_code',e->>'sku',e->>'outcome',event_time) on conflict do nothing;get diagnostics inserted=row_count;if inserted=0 then continue;end if;
  perform pg_advisory_xact_lock(hashtextextended(concat(e->>'brand_slug',':',e->>'country_code',':',e->>'sku'),0));
  if e->>'outcome'='verified' then
   update public.operations_crawl_issues set status='auto_resolved',resolved_at=event_time,resolution='후속 공개 검증 성공',revision=revision+1 where brand_slug=e->>'brand_slug' and country_code=e->>'country_code' and sku=e->>'sku' and last_seen_at<=event_time and status in('open','manual_pending');
  else
   insert into public.operations_crawl_issues as old(brand_slug,country_code,sku,stage,kind,reason_code,official_url,first_seen_at,last_seen_at,run_key) values(e->>'brand_slug',e->>'country_code',e->>'sku',e->>'stage',e->>'outcome',e->>'reason_code',e->>'official_url',event_time,event_time,p_run_key)
   on conflict(brand_slug,country_code,sku,stage) do update set occurrences=old.occurrences+1,first_seen_at=least(old.first_seen_at,excluded.first_seen_at),last_seen_at=greatest(old.last_seen_at,excluded.last_seen_at),kind=case when excluded.last_seen_at>=old.last_seen_at then excluded.kind else old.kind end,reason_code=case when excluded.last_seen_at>=old.last_seen_at then excluded.reason_code else old.reason_code end,official_url=case when excluded.last_seen_at>=old.last_seen_at then excluded.official_url else old.official_url end,run_key=case when excluded.last_seen_at>=old.last_seen_at then excluded.run_key else old.run_key end,status=case when excluded.last_seen_at>coalesce(old.resolved_at,old.last_seen_at) then 'open' else old.status end,revision=old.revision+1 returning * into i;
   -- A later public receipt must also protect against replaying old failed artifacts.
   update public.operations_crawl_issues set status='auto_resolved',resolved_at=(select max(v.observed_at) from public.operations_crawl_issue_events v where v.brand_slug=i.brand_slug and v.country_code=i.country_code and v.sku=i.sku and v.outcome='verified' and v.observed_at>=i.last_seen_at),resolution='후속 공개 검증 성공' where id=i.id and status in('open','manual_pending') and exists(select 1 from public.operations_crawl_issue_events v where v.brand_slug=i.brand_slug and v.country_code=i.country_code and v.sku=i.sku and v.outcome='verified' and v.observed_at>=i.last_seen_at);
   update public.operations_crawl_issue_events set issue_id=i.id where event_key=e->>'event_key';
  end if;n:=n+1;
 end loop;
 insert into public.operations_crawl_sync_runs as old(run_key,source,finished,received_count) values(p_run_key,p_source,p_finished,n) on conflict(run_key) do update set last_sync_at=now(),finished=old.finished or p_finished,received_count=old.received_count+n;
 return jsonb_build_object('accepted',n);end $$;
create function public.operations_crawl_issue_target(p_id uuid) returns jsonb language plpgsql security invoker set search_path='' as $$declare i public.operations_crawl_issues;v public.product_variants;begin
 select * into i from public.operations_crawl_issues where id=p_id;if not found then raise exception 'issue_missing';end if;
 select p.* into v from public.product_variants p join public.brands b on b.id=p.brand_id where b.slug=i.brand_slug and p.normalized_code=i.sku;
 return jsonb_build_object('issue',to_jsonb(i),'variant',case when v.id is null then null else to_jsonb(v) end);end $$;
create function public.operations_complete_crawl_issue(p_actor uuid,p_id uuid,p_revision integer,p_snapshot_revision bigint,p_reason text) returns uuid language plpgsql security invoker set search_path='' as $$declare i public.operations_crawl_issues;v public.product_variants;m public.market_products;begin
 if not exists(select 1 from public.operations_administrator where user_id=p_actor) or length(btrim(p_reason)) not between 1 and 1000 then raise exception 'invalid_admin';end if;
 select * into i from public.operations_crawl_issues where id=p_id for update;if not found or i.revision<>p_revision then raise exception 'issue_conflict';end if;
 select p.* into v from public.product_variants p join public.brands b on b.id=p.brand_id where b.slug=i.brand_slug and p.normalized_code=i.sku and p.active and b.active;
 if v.id is null or nullif(btrim(v.name_ko),'') is null or nullif(btrim(v.material_ko),'') is null or not exists(select 1 from public.product_media where variant_id=v.id and is_primary) then raise exception 'product_incomplete';end if;
 select * into m from public.market_products where variant_id=v.id and country_code=i.country_code;
 if m.current_price is null or m.current_price<=0 or m.price_status<>'confirmed' or m.price_checked_at is null or m.price_checked_at>now()+interval '1 minute' or m.currency_code<>(case i.country_code when 'KR' then 'KRW' when 'JP' then 'JPY' when 'US' then 'USD' when 'SG' then 'SGD' when 'HK' then 'HKD' else 'EUR' end) then raise exception 'price_incomplete';end if;
 if p_snapshot_revision is null or p_snapshot_revision<>(select revision from public.comparison_catalog_state where id) then raise exception 'publication_pending';end if;
 update public.operations_crawl_issues set status='published',resolution=p_reason,resolved_at=now(),revision=revision+1 where id=p_id;
 insert into public.operations_audit(actor_id,action,target,before_value,after_value,reason) values(p_actor,'complete_crawl_issue',p_id::text,to_jsonb(i),jsonb_build_object('status','published','variant_id',v.id,'snapshot_revision',p_snapshot_revision),p_reason);return v.id;end $$;
create function public.operations_crawl_issue_action(p_actor uuid,p_id uuid,p_revision integer,p_status text,p_reason text) returns void language plpgsql security invoker set search_path='' as $$declare i public.operations_crawl_issues;begin
 if not exists(select 1 from public.operations_administrator where user_id=p_actor) or p_status not in('manual_pending','dismissed') or length(btrim(p_reason)) not between 1 and 1000 then raise exception 'invalid_admin';end if;
 select * into i from public.operations_crawl_issues where id=p_id for update;if not found or i.revision<>p_revision then raise exception 'issue_conflict';end if;
 update public.operations_crawl_issues set status=p_status,revision=revision+1,resolution=p_reason,resolved_at=case when p_status='dismissed' then now() else null end where id=p_id;
 insert into public.operations_audit(actor_id,action,target,before_value,after_value,reason) values(p_actor,'action_crawl_issue',p_id::text,to_jsonb(i),jsonb_build_object('status',p_status),p_reason);end $$;
create function public.operations_crawl_issue_stats() returns jsonb language sql security invoker set search_path='' as $$select jsonb_build_object('openFailures',count(*) filter(where kind='failure' and status in('open','manual_pending')),'unavailable',count(*) filter(where kind='price_unavailable' and status in('open','manual_pending')),'published',count(*) filter(where status='published'),'resolved',count(*) filter(where status='auto_resolved'),'total',count(*)) from public.operations_crawl_issues$$;
do $$declare f record;begin for f in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname in('operations_record_crawl_events','operations_crawl_issue_target','operations_complete_crawl_issue','operations_crawl_issue_action','operations_crawl_issue_stats') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
notify pgrst,'reload schema';
commit;
